{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "title_h2",
        "intro_text",
        "contact_info_card",
        "date_card",
        "hiring_manager_card",
        "salutation_card",
        "para1_card",
        "para2_card",
        "para3_card",
        "para4_card",
        "closing_card"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Senior Marketing Manager Cover Letter Outline",
        "variant": "h1"
      },
      "children": []
    },
    "title_h2": {
      "type": "Text",
      "props": {
        "text": "Non-Profit Cover Letter Structure",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This outline provides a comprehensive structure for an experienced marketing manager applying for a senior position within a non-profit organization, emphasizing transferable skills and mission alignment.",
        "variant": "body"
      },
      "children": []
    },
    "contact_info_card": {
      "type": "Card",
      "props": {},
      "children": [
        "contact_info_stack"
      ]
    },
    "contact_info_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "contact_info_heading",
        "contact_info_name",
        "contact_info_address",
        "contact_info_phone",
        "contact_info_email",
        "contact_info_linkedin"
      ]
    },
    "contact_info_heading": {
      "type": "Text",
      "props": {
        "text": "Your Contact Information",
        "variant": "h3"
      },
      "children": []
    },
    "contact_info_name": {
      "type": "Text",
      "props": {
        "text": "• [Your Name]",
        "variant": "body"
      },
      "children": []
    },
    "contact_info_address": {
      "type": "Text",
      "props": {
        "text": "• [Your Address]",
        "variant": "body"
      },
      "children": []
    },
    "contact_info_phone": {
      "type": "Text",
      "props": {
        "text": "• [Your Phone Number]",
        "variant": "body"
      },
      "children": []
    },
    "contact_info_email": {
      "type": "Text",
      "props": {
        "text": "• [Your Email Address]",
        "variant": "body"
      },
      "children": []
    },
    "contact_info_linkedin": {
      "type": "Text",
      "props": {
        "text": "• [Your LinkedIn Profile URL (Optional)]",
        "variant": "body"
      },
      "children": []
    },
    "date_card": {
      "type": "Card",
      "props": {},
      "children": [
        "date_stack"
      ]
    },
    "date_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "date_heading",
        "date_value"
      ]
    },
    "date_heading": {
      "type": "Text",
      "props": {
        "text": "Date",
        "variant": "h3"
      },
      "children": []
    },
    "date_value": {
      "type": "Text",
      "props": {
        "text": "• [Date of Application]",
        "variant": "body"
      },
      "children": []
    },
    "hiring_manager_card": {
      "type": "Card",
      "props": {},
      "children": [
        "hiring_manager_stack"
      ]
    },
    "hiring_manager_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "hiring_manager_heading",
        "hiring_manager_name",
        "hiring_manager_title",
        "hiring_manager_org",
        "hiring_manager_address"
      ]
    },
    "hiring_manager_heading": {
      "type": "Text",
      "props": {
        "text": "Hiring Manager Contact Information",
        "variant": "h3"
      },
      "children": []
    },
    "hiring_manager_name": {
      "type": "Text",
      "props": {
        "text": "• [Hiring Manager Name, if known, or \"Hiring Team\"]",
        "variant": "body"
      },
      "children": []
    },
    "hiring_manager_title": {
      "type": "Text",
      "props": {
        "text": "• [Hiring Manager Title]",
        "variant": "body"
      },
      "children": []
    },
    "hiring_manager_org": {
      "type": "Text",
      "props": {
        "text": "• [Non-Profit Organization Name]",
        "variant": "body"
      },
      "children": []
    },
    "hiring_manager_address": {
      "type": "Text",
      "props": {
        "text": "• [Non-Profit Organization Address]",
        "variant": "body"
      },
      "children": []
    },
    "salutation_card": {
      "type": "Card",
      "props": {},
      "children": [
        "salutation_stack"
      ]
    },
    "salutation_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "salutation_heading",
        "salutation_known",
        "salutation_unknown"
      ]
    },
    "salutation_heading": {
      "type": "Text",
      "props": {
        "text": "Salutation",
        "variant": "h3"
      },
      "children": []
    },
    "salutation_known": {
      "type": "Text",
      "props": {
        "text": "• Dear [Mr./Ms./Mx. Last Name], (If name is known)",
        "variant": "body"
      },
      "children": []
    },
    "salutation_unknown": {
      "type": "Text",
      "props": {
        "text": "• Dear Hiring Team, (If name is unknown)",
        "variant": "body"
      },
      "children": []
    },
    "para1_card": {
      "type": "Card",
      "props": {},
      "children": [
        "para1_stack"
      ]
    },
    "para1_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "para1_heading",
        "para1_bullet1",
        "para1_bullet2",
        "para1_bullet3",
        "para1_bullet4",
        "para1_example"
      ]
    },
    "para1_heading": {
      "type": "Text",
      "props": {
        "text": "Paragraph 1: Introduction - Express Enthusiasm & Fit",
        "variant": "h3"
      },
      "children": []
    },
    "para1_bullet1": {
      "type": "Text",
      "props": {
        "text": "• Clearly state the specific senior marketing manager position you are applying for.",
        "variant": "body"
      },
      "children": []
    },
    "para1_bullet2": {
      "type": "Text",
      "props": {
        "text": "• Mention where you discovered the job posting (e.g., LinkedIn, organization website, referral).",
        "variant": "body"
      },
      "children": []
    },
    "para1_bullet3": {
      "type": "Text",
      "props": {
        "text": "• Briefly state your strong interest and highlight your proven marketing leadership experience.",
        "variant": "body"
      },
      "children": []
    },
    "para1_bullet4": {
      "type": "Text",
      "props": {
        "text": "• Immediately connect your professional background and passion to the non-profit's mission or the sector's importance.",
        "variant": "body"
      },
      "children": []
    },
    "para1_example": {
      "type": "Text",
      "props": {
        "text": "Example: \"I am writing to express my keen interest in the Senior Marketing Manager position at [Non-Profit Organization Name], as advertised on [Platform]. With over X years of experience leading successful marketing strategies in [previous industry/sector], I am eager to apply my expertise to advance your critical mission of [mention key aspect of mission].\"",
        "variant": "body"
      },
      "children": []
    },
    "para2_card": {
      "type": "Card",
      "props": {},
      "children": [
        "para2_stack"
      ]
    },
    "para2_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "para2_heading",
        "para2_bullet1",
        "para2_bullet2",
        "para2_bullet3",
        "para2_bullet4",
        "para2_example"
      ]
    },
    "para2_heading": {
      "type": "Text",
      "props": {
        "text": "Paragraph 2: Body - Transferable Skills & Achievements",
        "variant": "h3"
      },
      "children": []
    },
    "para2_bullet1": {
      "type": "Text",
      "props": {
        "text": "• Elaborate on your commercial marketing experience, specifically detailing how your skills are directly transferable and valuable to a non-profit context.",
        "variant": "body"
      },
      "children": []
    },
    "para2_bullet2": {
      "type": "Text",
      "props": {
        "text": "• Highlight key competencies: strategic planning, digital marketing (SEO, SEM, social media), brand building, content creation, audience engagement, campaign management, data analysis, and team leadership.",
        "variant": "body"
      },
      "children": []
    },
    "para2_bullet3": {
      "type": "Text",
      "props": {
        "text": "• Provide 1-2 quantifiable achievements from previous roles that demonstrate impact (e.g., increased brand awareness by X%, successfully launched Y campaigns, managed budgets of Z, grew online community by W%).",
        "variant": "body"
      },
      "children": []
    },
    "para2_bullet4": {
      "type": "Text",
      "props": {
        "text": "• Emphasize your understanding of non-profit specific needs, such as donor acquisition, advocacy campaigns, community outreach, and volunteer engagement.",
        "variant": "body"
      },
      "children": []
    },
    "para2_example": {
      "type": "Text",
      "props": {
        "text": "Example: \"In my previous role as Marketing Manager at [Previous Company], I successfully developed and executed multi-channel campaigns that resulted in [quantifiable achievement, e.g., 30% increase in lead generation]. I am confident that my strategic approach to brand development and audience segmentation can be effectively leveraged to enhance [Non-Profit Organization Name]'s fundraising efforts and expand its reach among key stakeholders, driving meaningful impact.\"",
        "variant": "body"
      },
      "children": []
    },
    "para3_card": {
      "type": "Card",
      "props": {},
      "children": [
        "para3_stack"
      ]
    },
    "para3_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "para3_heading",
        "para3_bullet1",
        "para3_bullet2",
        "para3_bullet3",
        "para3_bullet4",
        "para3_example"
      ]
    },
    "para3_heading": {
      "type": "Text",
      "props": {
        "text": "Paragraph 3: Body - Passion for Mission & Strategic Vision",
        "variant": "h3"
      },
      "children": []
    },
    "para3_bullet1": {
      "type": "Text",
      "props": {
        "text": "• Explain why you are specifically passionate about this particular non-profit's mission, values, and work.",
        "variant": "body"
      },
      "children": []
    },
    "para3_bullet2": {
      "type": "Text",
      "props": {
        "text": "• Demonstrate that you have thoroughly researched the organization; mention a specific program, initiative, or achievement that resonates with you.",
        "variant": "body"
      },
      "children": []
    },
    "para3_bullet3": {
      "type": "Text",
      "props": {
        "text": "• Outline how your leadership style and strategic vision align with the organization's current goals or future aspirations.",
        "variant": "body"
      },
      "children": []
    },
    "para3_bullet4": {
      "type": "Text",
      "props": {
        "text": "• Showcase relevant soft skills: collaboration, innovation, problem-solving, and a deep dedication to social impact.",
        "variant": "body"
      },
      "children": []
    },
    "para3_example": {
      "type": "Text",
      "props": {
        "text": "Example: \"My commitment to [mention specific cause, e.g., environmental conservation, youth empowerment, social justice] aligns perfectly with [Non-Profit Organization Name]'s impactful work. I am particularly inspired by your recent [mention a specific program or initiative], and I believe my experience in [specific skill, e.g., building community partnerships, driving digital engagement] would be instrumental in achieving your strategic objectives and amplifying your message to a broader audience.\"",
        "variant": "body"
      },
      "children": []
    },
    "para4_card": {
      "type": "Card",
      "props": {},
      "children": [
        "para4_stack"
      ]
    },
    "para4_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "para4_heading",
        "para4_bullet1",
        "para4_bullet2",
        "para4_bullet3",
        "para4_example"
      ]
    },
    "para4_heading": {
      "type": "Text",
      "props": {
        "text": "Paragraph 4: Call to Action & Closing",
        "variant": "h3"
      },
      "children": []
    },
    "para4_bullet1": {
      "type": "Text",
      "props": {
        "text": "• Reiterate your strong interest in the role and the opportunity to contribute to the organization.",
        "variant": "body"
      },
      "children": []
    },
    "para4_bullet2": {
      "type": "Text",
      "props": {
        "text": "• Express eagerness to discuss your qualifications further in an interview.",
        "variant": "body"
      },
      "children": []
    },
    "para4_bullet3": {
      "type": "Text",
      "props": {
        "text": "• Confirm that your resume is attached for their review.",
        "variant": "body"
      },
      "children": []
    },
    "para4_example": {
      "type": "Text",
      "props": {
        "text": "Example: \"Thank you for considering my application. I am enthusiastic about the opportunity to contribute my skills and passion to [Non-Profit Organization Name] and would welcome an interview to discuss how my experience can benefit your team. My resume is attached for your review and provides further detail on my qualifications.\"",
        "variant": "body"
      },
      "children": []
    },
    "closing_card": {
      "type": "Card",
      "props": {},
      "children": [
        "closing_stack"
      ]
    },
    "closing_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "closing_heading",
        "closing_sincerely",
        "closing_name"
      ]
    },
    "closing_heading": {
      "type": "Text",
      "props": {
        "text": "Professional Closing",
        "variant": "h3"
      },
      "children": []
    },
    "closing_sincerely": {
      "type": "Text",
      "props": {
        "text": "• Sincerely,",
        "variant": "body"
      },
      "children": []
    },
    "closing_name": {
      "type": "Text",
      "props": {
        "text": "• [Your Typed Name]",
        "variant": "body"
      },
      "children": []
    }
  }
}
